def scrub_legacy_manifest_key_material(apps, schema_editor):
    """Remove stored key/signature payloads from historical canonical manifests."""
    if schema_editor.connection.vendor != "postgresql":
        return

    Manifest = apps.get_model("signing", "SigningManifest")
    connection = schema_editor.connection
    with connection.cursor() as cursor:
        cursor.execute("ALTER TABLE signing_manifest DISABLE TRIGGER trg_signing_manifest_protect")
        try:
            for manifest in Manifest.objects.all().iterator(chunk_size=500):
                content = manifest.noi_dung_chuan_hoa
                if not isinstance(content, dict):
                    continue
                changed = False
                for level in content.get("cap_ky", []):
                    for signer in level.get("nguoi_ky", []):
                        signature = signer.get("chu_ky")
                        if signature is None:
                            continue
                        clean = {
                            key: signature[key]
                            for key in (
                                "id", "hash_tai_lieu", "ngay_ky", "ky_tre_han", "so_giay_tre",
                                "ghi_chu_ky", "ma_bam_anh_chu_ky",
                            )
                            if key in signature
                        }
                        clean["phuong_thuc"] = "PIN"
                        if clean != signature:
                            signer["chu_ky"] = clean
                            changed = True
                if content.get("phien_ban") != 3:
                    content["phien_ban"] = 3
                    changed = True
                if not changed:
                    continue

                canonical = json.dumps(content, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
                digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
                cursor.execute(
                    "UPDATE signing_manifest SET noi_dung_chuan_hoa = %s::jsonb, ma_bam_bang_chung = %s WHERE id = %s",
                    [canonical, digest, manifest.pk],
                )
        finally:
            cursor.execute("ALTER TABLE signing_manifest ENABLE TRIGGER trg_signing_manifest_protect")


def reject_reverse_scrub(apps, schema_editor):
    raise IrreversibleError(
        "Signing key material was removed from historical manifests and cannot be restored."
    )


